const lockOpenAgentExecutionContextsForAgentRevocation = `-- name: LockOpenAgentExecutionContextsForAgentRevocation :many
SELECT context.context_key
FROM agent_execution_contexts context
WHERE context.tenant_id=$1::text
  AND context.agent_actor_id=$2::text
  AND (
    context.terminal_reason IS NULL
    OR (context.context_kind='meta'
        AND context.room_id=ANY($3::text[]))
  )
ORDER BY context.context_key
FOR UPDATE
`

type LockOpenAgentExecutionContextsForAgentRevocationParams struct {
	TenantID     string   `json:"tenant_id"`
	AgentActorID string   `json:"agent_actor_id"`
	RoomIds      []string `json:"room_ids"`
}

// One ordered pass over every Context the deletion touches: open Contexts it
// terminates, plus the meta Contexts membership revocation suspends in its
// Rooms (LockMetaContextsForRoomMemberships), terminal or not.
func (q *Queries) LockOpenAgentExecutionContextsForAgentRevocation(ctx context.Context, arg LockOpenAgentExecutionContextsForAgentRevocationParams) ([]string, error) {
	rows, err := q.db.Query(ctx, lockOpenAgentExecutionContextsForAgentRevocation, arg.TenantID, arg.AgentActorID, arg.RoomIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var context_key string
		if err := rows.Scan(&context_key); err != nil {
			return nil, err
		}
		items = append(items, context_key)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

