const touchAgentRuntimeLocalComputer = `-- name: TouchAgentRuntimeLocalComputer :one
UPDATE local_computers
SET status=$1::text,
    runtime_inventory=COALESCE($2::jsonb,runtime_inventory),
    runtime_diagnostics=COALESCE($3::jsonb,runtime_diagnostics),
    daemon_version=COALESCE($4::text,daemon_version),
    recommended_version=COALESCE($5::text,recommended_version),
    active_operations=CASE WHEN $1::text='online'
        THEN COALESCE($6::integer,active_operations) ELSE 0 END,
    last_seen_at=$7::timestamptz,
    updated_at=clock_timestamp()
WHERE computer_id=$8::text AND status<>'removed'
RETURNING computer_id, display_name, status, credential_generation, capacity, active_operations, runtime_inventory, workspace_grants, runtime_diagnostics, last_seen_at, removed_at, created_at, updated_at, daemon_id, daemon_public_key, daemon_identity_version, platform, daemon_version, recommended_version, owner_tenant_id, owner_actor_id
`

type TouchAgentRuntimeLocalComputerParams struct {
	Status             string             `json:"status"`
	RuntimeInventory   []byte             `json:"runtime_inventory"`
	RuntimeDiagnostics []byte             `json:"runtime_diagnostics"`
	DaemonVersion      pgtype.Text        `json:"daemon_version"`
	RecommendedVersion pgtype.Text        `json:"recommended_version"`
	ActiveOperations   pgtype.Int4        `json:"active_operations"`
	LastSeenAt         pgtype.Timestamptz `json:"last_seen_at"`
	ComputerID         string             `json:"computer_id"`
}

func (q *Queries) TouchAgentRuntimeLocalComputer(ctx context.Context, arg TouchAgentRuntimeLocalComputerParams) (LocalComputer, error) {
	row := q.db.QueryRow(ctx, touchAgentRuntimeLocalComputer,
		arg.Status,
		arg.RuntimeInventory,
		arg.RuntimeDiagnostics,
		arg.DaemonVersion,
		arg.RecommendedVersion,
		arg.ActiveOperations,
		arg.LastSeenAt,
		arg.ComputerID,
	)
	var i LocalComputer
	err := row.Scan(
		&i.ComputerID,
		&i.DisplayName,
		&i.Status,
		&i.CredentialGeneration,
		&i.Capacity,
		&i.ActiveOperations,
		&i.RuntimeInventory,
		&i.WorkspaceGrants,
		&i.RuntimeDiagnostics,
		&i.LastSeenAt,
		&i.RemovedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DaemonID,
		&i.DaemonPublicKey,
		&i.DaemonIdentityVersion,
		&i.Platform,
		&i.DaemonVersion,
		&i.RecommendedVersion,
		&i.OwnerTenantID,
		&i.OwnerActorID,
	)
	return i, err
}

const upsertAgentPerRoomMetaContext = `-- name: UpsertAgentPerRoomMetaContext :execrows
INSERT INTO agent_execution_contexts(
    context_key,tenant_id,agent_actor_id,agent_management_id,
    context_kind,room_id,membership_epoch_id,target_residency
) VALUES(
    $1::text,$2::text,
    $3::text,$4::text,
    'meta',$5::text,$6::text,
    'suspended'
)
ON CONFLICT(context_key) DO UPDATE SET
    membership_epoch_id=excluded.membership_epoch_id,
    target_residency='active',
    terminal_reason=NULL,terminated_at=NULL,
    state_revision=agent_execution_contexts.state_revision+1,
    updated_at=clock_timestamp()
WHERE agent_execution_contexts.tenant_id=excluded.tenant_id
  AND agent_execution_contexts.agent_actor_id=excluded.agent_actor_id
  AND agent_execution_contexts.agent_management_id=excluded.agent_management_id
  AND agent_execution_contexts.context_kind='meta'
  AND agent_execution_contexts.task_id IS NULL
  AND agent_execution_contexts.room_id=excluded.room_id
  AND (agent_execution_contexts.terminal_reason IS NULL OR agent_execution_contexts.terminal_reason='context_deleted')
  AND agent_execution_contexts.membership_epoch_id IS DISTINCT FROM excluded.membership_epoch_id
  AND EXISTS (
      SELECT 1 FROM room_members membership
      WHERE membership.room_id=excluded.room_id
        AND membership.actor_id=excluded.agent_actor_id
        AND membership.membership_epoch_id=excluded.membership_epoch_id
  )
`

type UpsertAgentPerRoomMetaContextParams struct {
	ContextKey        string `json:"context_key"`
	TenantID          string `json:"tenant_id"`
	AgentActorID      string `json:"agent_actor_id"`
	AgentManagementID string `json:"agent_management_id"`
	RoomID            string `json:"room_id"`
	MembershipEpochID string `json:"membership_epoch_id"`
}

func (q *Queries) UpsertAgentPerRoomMetaContext(ctx context.Context, arg UpsertAgentPerRoomMetaContextParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertAgentPerRoomMetaContext,
		arg.ContextKey,
		arg.TenantID,
		arg.AgentActorID,
		arg.AgentManagementID,
		arg.RoomID,
		arg.MembershipEpochID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
